const missing = REQUIRED.filter((key) => draft[key] === undefined || draft[key] === '');
if (missing.length) return [{ json: { chat_id: input.chat_id, outcome: 'empty', reply: msg(lang, 'nothing') } }];
const key = dupKey(draft);
const duplicate = rows.find((row) => String(row.dup_key) === key);
